pub fn resolve_pre_cursor(
    runner: &dyn CommandRunner,
    cwd: &Path,
    package: &PackageId,
) -> Result<Option<CommitSha>, ConventionalError> {
    let ref_name = pre_cursor_ref_name(package);
    let output = runner.run("git", &["rev-parse", "--verify", "--quiet", &ref_name], cwd)?;

    if !output.success() {
        return Ok(None);
    }

    let sha_str = output.stdout_trimmed();
    if sha_str.is_empty() {
        return Ok(None);
    }

    let sha = CommitSha::parse(sha_str).map_err(|source| ConventionalError::MalformedPreCursorRef {
        cwd: cwd.to_path_buf(),
        ref_name,
        stderr: output.redacted_stderr(),
        source,
    })?;

    Ok(Some(sha))
}

